import {uid,dateKey,addDays,monday,minutes,endTime,overlap,unavailableOn,slotsOn,conflicts,load,moveTask,snapshotDay,seed,inboxTasks,findTask,tasksInSlot,placeTask,stashTask,deleteTask,restoreTask,suggestStart,pastMinutes,canSchedule,canPlaceInSlot,slotOccupancy,timelineLanes,changeSlotTiming,scheduleNewTask,emptyPlan,backlogTasks,backlogCounts,categorizedMeetings,planningTotals} from './model.js?v=20261127-event-colors';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const API_BASE=globalThis.PARAVOZIKI_API_BASE||'';let sessionToken='';try{sessionToken=sessionStorage.getItem('paravoziki.session')||'';}catch{}
let coachGesture=null,suppressCoachClickUntil=0;let calendarConnection=null,calendarBusy=false;let lastDeletion=null,toastTimeout=null,draggedEntity=null,suppressPaletteClickUntil=0;let telegramConnection=null;let KEY='rhythm.v1';let account=null,revision=0,authMode='login',pendingPlan=null,syncBusy=false,syncTimeout=null,syncBlocked=false;let state;try{state=JSON.parse(localStorage.getItem(KEY))||emptyPlan();}catch{state=emptyPlan();}
let view='week',week=monday(dateKey()),day=dateKey(),wizard=null,selectedCategory=null,blockFilter='week',inboxPeriod='all',inboxReason='all',remoteRevision=0,remoteBusy=false;
const days=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'],fullDays=['Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'];
const cat=id=>state.categories.find(c=>c.id===id)||{name:'Без вагончика',color:'#ffffff',tag:''};
const fmt=n=>`${Math.round(n/60*10)/10} ч`,dateFmt=k=>new Date(k+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short'});
const btn=(text,action,data='',cls='')=>`<button class="${cls}" data-action="${action}" ${data}>${text}</button>`;
function save(){if(!account)return;pendingPlan=structuredClone(state);cachePlan(true);clearTimeout(syncTimeout);syncTimeout=setTimeout(flushPlan,500);}
function cachePlan(dirty){try{localStorage.setItem(KEY,JSON.stringify({state,revision,dirty}));}catch{toast('Локальная резервная копия недоступна.');}}
function toast(text,undo=false){if($('#modal')?.open){let notice=$('#modal .dialog-notice');if(!notice){notice=document.createElement('div');notice.className='notice dialog-notice';notice.setAttribute('role','alert');$('#modal').append(notice);}notice.textContent=text;return;}clearTimeout(toastTimeout);$('#toast').innerHTML=esc(text)+(undo?' '+btn('Отменить удаление','undo-delete','','small'):'');$('#toast').style.display='block';toastTimeout=setTimeout(()=>$('#toast').style.display='none',undo?20000:4500);}
function modal(title,body){$('#modal').innerHTML=`<h2>${title}</h2>${body}`;if(!$('#modal').open)$('#modal').showModal();}
function close(){$('#modal').close();wizard=null;}
function actions(extra=''){return `<div class="actions">${btn('Отмена','close')}${extra}</div>`;}
function field(label,input){return `<label>${label}${input}</label>`;}
function input(name,type='text',value='',attrs=''){return `<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}>`;}
function select(name,options,value){return `<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select>`;}
function categorySelect(value){return select('category',state.categories.map(c=>[c.id,c.name]),value);}
function render(){const previousScroll=$('.timeline-scroll'),scrollTop=previousScroll?.scrollTop,scrollLeft=previousScroll?.scrollLeft;const titles={week:'Неделя',day:'Мой день',results:'Итоги',settings:'Настройки',blocks:'Вагончики',backlog:'Накопитель'};
$('#app').innerHTML=`<div class="layout"><header class="app-header"><div class="brand"><img src="logo.svg" alt="" width="45" height="40"><span>паровозики</span></div><nav aria-label="Основное меню">${Object.entries(titles).map(([id,t])=>btn(navLabel(id,t),'nav',`data-view="${id}"`,id===view?'active':'')).join('')}</nav><div class="header-account"><span class="account-email">${esc(account?.email||'')}</span>${btn('Выйти','logout','','small soft')}<div id="sync-status" class="small">План в вашем аккаунте</div></div></header><main class="main">${view==='week'?renderWagonYard():'<div class="train-banner"><img src="train.svg" alt="" aria-hidden="true"></div>'}${view==='week'?'':renderTopbar(titles[view])}<div id="remote-notice" role="status"></div>${({week:renderWeek,day:renderDay,results:renderResults,settings:renderSettings,blocks:renderBlocks,backlog:renderBacklog})[view]() }</main></div>`;updateClock();updateRemoteNotice();const timeline=$('.timeline-scroll');if(timeline){timeline.scrollTop=scrollTop??0;timeline.scrollLeft=scrollLeft??0;}}
function heading(title,sub,controls=''){return `<div class="heading"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${controls}</div></div>`;}
function stats(items){return `<div class="stats">${items.map(([label,val,note])=>`<div class="stat"><span class="muted">${label}</span><strong>${val}</strong><small>${note}</small></div>`).join('')}</div>`;}
function renderWeek(){const dates=Array.from({length:7},(_,i)=>addDays(week,i)),ss=state.slots.filter(s=>dates.includes(s.date)),ts=state.tasks.filter(t=>dates.includes(t.date));const totals=planningTotals(state,dates);let overs=0;for(const d of dates)for(const c of state.categories)overs+=load(state,c.id,d).overflow;const issues=conflicts(state).filter(c=>ss.some(s=>s.id===c.slot));return `<div class="week-layout"><section class="week-rail" aria-label="Панель недели">${renderBacklogCounters()}${renderBacklogTray()}${!state.slots.length&&!state.tasks.length&&!(state.backlog||[]).length?`<section class="account-onboarding"><h2>Ваше пространство</h2>${btn('Подключить Telegram','open-connections')}${btn('Подключить календарь','calendar-connect')}</section>`:''}${renderTopbar('Неделя')}${heading('Неделя','Распределите время между важными направлениями.',btn('Шаблон недели','template')+btn('+ Добавить задачу','task','','primary'))}</section><section class="week-content" aria-label="Календарь недели"><div class="calendar-toolbar"><div class="week-tools"><div class="actions">${btn('←','week-prev','aria-label="Предыдущая неделя"')}<span class="week-label">${dateFmt(week)} — ${dateFmt(addDays(week,6))}</span>${btn('→','week-next','aria-label="Следующая неделя"')}${btn('Корректировка','adjust','title="Перегрузка и пересечения расписания"')}</div>${stats([['Время в вагончиках',fmt(totals.budget),'Интервалы и встречи с категорией'],['Запланировано',fmt(totals.planned),`${ts.length} дел · ${totals.meetingCount} встреч`],['Перегрузка',fmt(overs),overs?'Есть задачи для корректировки':'Всё помещается в вагончики']])}</div>${quickBacklogForm()}</div>${issues.length?`<div class="notice">${issues.map(i=>esc(i.text)).join('<br>')}</div>`:''}${renderTimeline(dates)}</section></div>`;}

function slotCard(s){const c=cat(s.category),l=load(state,c.id,s.date),ts=tasksInSlot(state,s);return `<div class="block" data-slot-id="${s.id}" role="group" aria-label="${esc(c.name)} ${s.date} ${s.start}" style="--color:${c.color}"><div class="slot-time"><div class="time">${s.start}–${endTime(s.start,s.duration)}</div>${btn('×','delete-slot',`data-id="${s.id}" aria-label="Удалить интервал ${esc(c.name)}" title="Удалить интервал"`,'icon-button task-delete')}</div><div class="slot-heading">${btn(esc(c.name),'open-block',`data-id="${c.id}"`,'block-title block-link')}${btn('✎','slot',`data-id="${s.id}" data-date="${s.date}" aria-label="Изменить интервал ${esc(c.name)}" title="Изменить интервал"`,'icon-button interval-edit')}</div><div class="capacity ${l.overflow?'warn':''}">${l.planned} / ${l.budget} мин за день</div><div class="bar"><span style="--color:${l.overflow?'#c77c58':c.color};width:${l.budget?l.planned/l.budget*100:0}%"></span></div>${ts.map(compactTask).join('')}</div>`;}

function dateControl(){return `<input id="selected-day" type="date" value="${day}" aria-label="Выбрать день" style="width:auto">`;}
function renderDay(){const ts=state.tasks.filter(t=>t.date===day),ss=slotsOn(state,day).sort((a,b)=>a.start.localeCompare(b.start)),started=!!state.baselines[day];return heading('Один день. Один фокус.','Начните с одной задачи, остальное уже в плане.',dateControl()+btn('+ Задача','task','','primary'))+`<div class="cols"><div>${!started?`<div class="panel"><h2>Готовы начать день?</h2><p class="muted">Зафиксируем исходный план, чтобы вечером сравнить его с результатом.</p>${btn('Запустить день','start-day','','primary')}</div>`:`<p class="pill">Исходный план сохранён · ${state.baselines[day].tasks.length} задач</p>`}${ss.length?ss.map(s=>{const c=cat(s.category),l=load(state,c.id,day);return `<div class="panel" data-slot-id="${s.id}" style="border-top:3px solid ${c.color}"><div class="actions" style="justify-content:space-between"><h2>${btn(esc(c.name),'open-block',`data-id="${c.id}"`,'block-link')}</h2><span class="muted">${s.start}–${endTime(s.start,s.duration)}</span></div><p class="small ${l.overflow?'warn':'muted'}">План ${l.planned} мин · факт ${Math.round(l.actual)} мин · доступно ${l.budget} мин</p>${tasksInSlot(state,s).map(taskRow).join('')||'<div class="empty">В этом интервале пока нет задач</div>'}</div>`;}).join(''):'<div class="panel empty">На этот день ещё нет интервалов.<br>Добавьте их в плане недели.</div>'}${ts.filter(t=>!ss.some(s=>s.category===t.category)).length?`<div class="panel"><h2>Без интервала</h2>${ts.filter(t=>!ss.some(s=>s.category===t.category)).map(taskRow).join('')}</div>`:''}</div><div>${timerPanel()}<div class="panel"><h2>Оставить место для жизни</h2><p class="muted">Незапланированное дело тоже занимает время. Добавьте его, чтобы увидеть реальную нагрузку.</p>${btn('+ Записать дело','task')}<hr style="border:0;border-top:1px solid #e5e8df;margin:22px 0"><p class="small muted">Помодоро: 25 минут фокуса, затем предложение сделать перерыв. Таймер считает время по часам, в том числе при свёрнутой вкладке.</p></div></div></div>`;}
function taskRow(t){return `<div class="task dense-task" style="--color:${cat(t.category).color}" draggable="${!t.done}" data-drag-kind="task" data-task-id="${t.id}"><div class="dense-task-header">${taskCheck(t)}${taskDurationControl(t)}<span class="task-category-label" title="${esc(cat(t.category).name)}">${esc(cat(t.category).name)}</span>${taskDelete(t)}</div><div class="dense-task-content"><div class="body ${t.done?'done':''}">${esc(t.title)}</div><div class="actions">${!t.done&&t.date?btn('▶','focus',`data-id="${t.id}" aria-label="Начать ${esc(t.title)}" title="Начать фокус"`,'icon-button task-focus'):''}${taskControls(t,false,true)}</div></div></div>`;}

function timerPanel(){const timer=state.timer,t=timer&&state.tasks.find(x=>x.id===timer.task);return `<div class="panel timer"><div class="eyebrow">Время фокуса</div><h2 style="margin-top:20px">${t?esc(t.title):'Выберите задачу'}</h2><div class="clock" id="clock">25:00</div><p class="muted small" id="timer-status">${timer?'Фокус-сессия':'Нажмите ▶ рядом с задачей'}</p><div class="actions">${timer?btn(timer.running?'Пауза':'Продолжить','timer-toggle','','primary')+btn('Завершить сессию','timer-stop'):''}</div></div>`;}
function renderBlocks(){if(!state.categories.length)return heading('Ваши вагончики','Назовите первый вагончик, чтобы собирать в него дела.',btn('Создать вагончик','category','','primary'));
 const c=cat(selectedCategory||state.categories[0]?.id);selectedCategory=state.categories.find(x=>x.id===selectedCategory)?.id||state.categories[0]?.id;
 const today=dateKey(),start=week,end=addDays(start,6);
 const tasks=state.tasks.filter(t=>t.category===selectedCategory&&(blockFilter==='all'||(blockFilter==='today'?t.date===today:t.date>=start&&t.date<=end))).sort((a,b)=>a.date.localeCompare(b.date)||Number(a.done)-Number(b.done)||a.title.localeCompare(b.title,'ru'));
 const meetings=categorizedMeetings(state,[...new Set(state.unavailable.map(e=>e.from))],selectedCategory).filter(e=>blockFilter==='all'||(blockFilter==='today'?e.from===today:e.from>=start&&e.from<=end));const dates=[...new Set([...tasks.map(t=>t.date),...meetings.map(e=>e.from)])].sort();const done=tasks.filter(t=>t.done).length;
 const period=blockFilter==='today'?'Сегодня, '+dateFmt(today):blockFilter==='week'?'Неделя: '+dateFmt(start)+' — '+dateFmt(end):'За всё время';
 return heading('Дела вагончика', 'Все задачи направления в одном месте.',btn('+ Добавить задачу','task','','primary'))+`<div class="actions block-tabs" aria-label="Выбор вагончика">${state.categories.map(x=>btn(`<span class="dot" style="--color:${x.color}"></span> ${esc(x.name)}`,'block-select',`data-id="${x.id}" aria-pressed="${x.id===selectedCategory}"`,x.id===selectedCategory?'primary':'')).join('')}</div><section class="panel"><div class="heading"><div><h2>${esc(cat(selectedCategory).name)}</h2><p class="subtitle">${period}</p></div><div class="actions" aria-label="Период задач">${[['today','Сегодня'],['week','Неделя'],['all','Все']].map(([key,label])=>btn(label,'block-filter',`data-filter="${key}" aria-pressed="${key===blockFilter}"`,key===blockFilter?'primary':'')).join('')}</div></div>${stats([['Дел и встреч',tasks.length+meetings.length,`${tasks.length-done} дел осталось · ${meetings.length} встреч`],['План',fmt(tasks.reduce((n,t)=>n+t.estimate,0)+meetings.reduce((n,e)=>n+e.duration,0)),'Дела и встречи календаря'],['Факт',fmt(tasks.reduce((n,t)=>n+t.actual,0)),'По этим задачам за всё время']])}${dates.map(d=>`<section class="block-date"><h3>${new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}${d===today?' · сегодня':''}</h3>${meetings.filter(e=>e.from===d).map(e=>`<div class="row"><span>${esc(e.title)}<small>${e.start}–${endTime(e.start,e.duration)} · ${e.duration} мин · Google Calendar</small></span>${btn('✎','busy-detail',`data-id="${e.id}" aria-label="Изменить встречу"`,'icon-button')}</div>`).join('')}${tasks.filter(t=>t.date===d).map(t=>`<div class="block-task">${taskRow(t)}<span class="pill ${!t.done&&!slotsOn(state,t.date).some(s=>s.category===t.category)?'warn':''}">${t.done?'Завершено':!slotsOn(state,t.date).some(s=>s.category===t.category)?'Нет интервала':'В плане'}</span></div>`).join('')}</section>`).join('')||`<div class="empty">${blockFilter==='all'?'В этом вагончике пока нет задач.':'За выбранный период задач нет.'}<br>Добавьте задачу или выберите другой период.</div>`}</section>`;
}
function renderResults(){const baseline=state.baselines[day],original=baseline?.tasks||state.tasks.filter(t=>t.date===day);const meetings=baseline?.calendar||categorizedMeetings(state,[day]);const planned=original.reduce((n,t)=>n+t.estimate,0)+meetings.reduce((n,e)=>n+e.duration,0),actual=state.sessions.filter(s=>s.date===day).reduce((n,s)=>n+s.minutes,0),moves=state.moves.filter(m=>m.from===day);const review=state.reviews[day]||{};return heading('Время без самообмана','Посмотрите на результат и отметьте, как вы себя чувствуете.',dateControl())+(!baseline?'<div class="notice">День ещё не запускался. Показан текущий план; исходный план не зафиксирован.</div>':'')+stats([['План на старте',fmt(planned),`${original.length} дел · ${meetings.length} встреч`],['Фактически',fmt(actual),'По завершённым фокус-сессиям'],['Перенесено',fmt(moves.reduce((n,m)=>n+m.minutes,0)),`${moves.length} переносов`]])+`<form id="review-form"><div class="review">${state.categories.map(c=>{const orig=original.filter(t=>t.category===c.id),done=orig.filter(t=>state.tasks.find(x=>x.id===t.id)?.done).length;const fact=state.sessions.filter(s=>s.date===day&&s.category===c.id).reduce((n,s)=>n+s.minutes,0);return `<div class="panel" style="border-top:3px solid ${c.color}"><h2>${esc(c.name)}</h2><p class="muted">${done} из ${orig.length} задач завершено · ${Math.round(fact)} мин фактически<br>Встречи: ${meetings.filter(e=>e.category===c.id).length} · ${meetings.filter(e=>e.category===c.id).reduce((n,e)=>n+e.duration,0)} мин в плане</p>${field('Насколько вы довольны результатом?',select(`rating-${c.id}`,[['','Без оценки'],['1','1 — совсем не довольна'],['2','2 — скорее не довольна'],['3','3 — нормально'],['4','4 — довольна'],['5','5 — очень довольна']],review.ratings?.[c.id]||''))}</div>`;}).join('')}</div><div class="panel"><h2>Что повлияло на день?</h2><p class="muted">${Math.abs(planned-actual)>=60?'План и факт заметно различаются. Можно записать причину.':'Комментарий поможет лучше спланировать следующую неделю.'}</p>${field('Причина',select('reason',[['','Не выбрана'],['hidden','Скрытые или незапланированные дела'],['complex','Задачи оказались сложнее'],['interruptions','Отвлечения'],['priorities','Изменились приоритеты'],['other','Другое']],review.reason||''))}${field('Комментарий',`<textarea name="comment" placeholder="Что стоит учесть в следующий раз?">${esc(review.comment||'')}</textarea>`)}<button class="primary">Сохранить итоги</button></div></form>`;}
function renderSettings(){return heading('Настроить под себя','Ваши вагончики, ограничения и шаблон недели.')+`<div class="settings-grid"><section class="panel"><div class="heading"><h2>Ваши вагончики</h2>${btn('+ Вагончик','category','','soft')}</div>${state.categories.map(c=>`<div class="row"><div><span class="dot" style="--color:${c.color}"></span> ${esc(c.name)}<small>#${esc(c.tag)}</small></div>${btn('Изменить','category',`data-id="${c.id}"`,'small')}</div>`).join('')}</section><section class="panel"><div class="heading"><h2>Занятое время</h2>${btn('+ Событие','unavailable','','soft')}</div><p class="muted small">Созвоны, курс и другие фиксированные события. Приложение проверяет пересечения с интервалами.</p>${state.unavailable.map(e=>`<div class="row"><div>${esc(e.title)}<small>${e.repeat==='weekly'?fullDays[e.weekday]+' · еженедельно':dateFmt(e.from)} · ${e.start}–${endTime(e.start,e.duration)}${e.until?' · до '+dateFmt(e.until):''}</small></div>${btn('✎','busy-detail',`data-id="${e.id}" aria-label="Изменить встречу"`,'icon-button')}${e.source==='google'?'<span class="small muted">Google Calendar</span>':btn('×','delete-event',`data-id="${e.id}" aria-label="Удалить событие"`)}</div>`).join('')||'<p class="muted">Событий пока нет.</p>'}</section>${telegramPanel()}${calendarPanel()}<section class="panel"><h2>Данные и шаблон</h2><p class="small muted">Аккаунт: ${esc(account?.email||'')}</p><p class="muted">План сохраняется в вашем аккаунте и доступен после входа на другом устройстве. Экспорт создаёт дополнительную резервную копию.</p><div class="actions">${btn('Экспорт JSON','export')}${btn('Импорт JSON','import')}</div><input type="file" id="import-file" accept="application/json" hidden><div class="row"><span class="muted small">Часовой пояс устройства</span><span class="small">${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}</span></div><div class="row"><span>Повторяемая неделя</span>${btn('Настроить','template')}</div></section></div>`;}
function showTask(){wizard={step:0,title:'',category:null,estimate:30,date:null};showWizard();}
function showWizard(){const w=wizard;let body=`<div class="steps">${[0,1,2,3,4].map(i=>`<span class="${i<=w.step?'on':''}"></span>`).join('')}</div>`;const titles=['Что нужно сделать?','В какой вагончик?','Сколько времени планируем?','На какой день?','Всё верно?'];if(w.step===0)body+=`<form id="wizard-title">${field('Название задачи',input('title','text',w.title,'required maxlength="240" autofocus'))}<div class="actions">${btn('Отмена','close')}<button class="primary">Дальше →</button></div></form>`;if(w.step===1)body+=`<div class="choices">${btn('Пока без вагончика','wizard-cat','data-id=""')}${state.categories.map(c=>btn(`<span class="dot" style="--color:${c.color}"></span> ${esc(c.name)}`,'wizard-cat',`data-id="${c.id}"`)).join('')}</div>`;if(w.step===2)body+=`<div class="choices">${[15,30,45,60,90,120].map(n=>btn(n+' мин','wizard-duration',`data-minutes="${n}"`)).join('')}</div><form id="wizard-custom" style="margin-top:18px">${field('Или своя длительность, минуты',input('estimate','number',w.estimate,'min="1" max="1440" required'))}<button>Дальше →</button></form>`;if(w.step===3)body+=`<div class="choices">${btn('Сегодня','wizard-date',`data-date="${dateKey()}"`)}${btn('Завтра','wizard-date',`data-date="${addDays(dateKey(),1)}"`)}${btn('В накопитель — без даты','wizard-backlog')}</div><p class="muted small">Ближайшие семь дней</p><div class="choices">${Array.from({length:7},(_,i)=>{const d=addDays(dateKey(),i);return btn(`${fullDays[(new Date(d+'T12:00:00').getDay()+6)%7]}<br><small>${dateFmt(d)}</small>`,'wizard-date',`data-date="${d}"`);}).join('')}</div><form id="wizard-calendar" style="margin-top:18px">${field('Или конкретная дата',input('date','date',w.date,'required'))}<button>Выбрать дату →</button></form>`;if(w.step===4){const l=load(state,w.category,w.date);body+=`<div class="chat"><strong>${esc(w.title)}</strong><br>${esc(cat(w.category).name)} · ${w.estimate} мин<br>${w.date?dateFmt(w.date):'Накопитель · без даты'}</div>`+(w.date===null?'<p class="muted">Задача не занимает время в расписании. Её можно будет запланировать позже.</p>':l.budget-l.actual-l.remaining<w.estimate?`<div class="notice">${!l.budget?'В этот день у вагончика нет интервала.':'Задача превышает свободное время вагончика на '+Math.ceil(w.estimate-(l.budget-l.actual-l.remaining))+' мин.'} Можно вернуться к выбору даты или сохранить в накопитель.</div>`:`<p class="muted">После добавления останется ${Math.floor(l.budget-l.actual-l.remaining-w.estimate)} мин.</p>`)+`<div class="actions">${btn('Изменить','wizard-reset')}${btn('Добавить задачу','wizard-save','','primary')}</div>`;}if(w.step>0)body+=`<div class="actions">${btn('Отмена','close')}${btn('← Назад','wizard-back')}</div>`;modal(titles[w.step],body);}
function showSlot(id,date,defaultCategory,defaultDuration){if(id&&state.slots.some(s=>s.id===id)){showCoachDetails(id,true);return;}if(!state.categories.length){showCategory();toast('Сначала назовите свой вагончик.');return;}if(date<dateKey()){toast('Этот день уже прошёл. Выберите будущую дату.');return;}const s=state.slots.find(x=>x.id===id);modal(s?'Изменить интервал':'Новый интервал',`<form id="slot-form" data-id="${id||''}">${field('Вагончик',categorySelect(s?.category||defaultCategory))}${field('Дата',input('date','date',date,'required'))}${field('Начало',input('start','time',s?.start||futureStart(date,defaultDuration||120),'required'))}${field('Продолжительность, минуты',input('duration','number',s?.duration||defaultDuration||120,'required min="15" max="1440" step="15"'))}${actions((s?btn('Удалить','delete-slot',`data-id="${s.id}"`,'danger'):'')+'<button class="primary">Сохранить</button>')}</form>`);}
function showCategory(id,defaultColor){const c=state.categories.find(x=>x.id===id);modal(c?'Настройки вагончика':'Новый вагончик',`<form id="category-form" data-id="${id||''}">${field('Название',input('name','text',c?.name||'','required maxlength="60"'))}${field('Telegram-тег',input('tag','text',c?.tag||'','required pattern="[A-Za-zА-Яа-яЁё0-9_]+"'))}${field('Цвет',input('color','color',c?.color||defaultColor||'#7c9a7d'))}${actions('<button class="primary">Сохранить</button>')}</form>`);}
function showUnavailable(defaultDate=day,defaultDuration=60){modal('Занятое время',`<form id="event-form">${field('Название',input('title','text','','required maxlength="100" placeholder="Например, созвон или перерыв"'))}${field('Повторение',select('repeat',[['once','Один раз'],['weekly','Еженедельно']],'once'))}${field('День недели (для повторения)',select('weekday',fullDays.map((s,i)=>[String(i),s]),String((new Date(defaultDate+'T12:00:00').getDay()+6)%7)))}${field('Дата / начало периода',input('from','date',defaultDate,'required'))}${field('Конец периода (необязательно)',input('until','date',''))}${field('Начало',input('start','time',futureStart(defaultDate,defaultDuration),'required'))}${field('Продолжительность, минуты',input('duration','number',defaultDuration,'required min="1" max="1440"'))}${actions('<button class="primary">Сохранить</button>')}</form>`);}
function showTemplate(){modal('Шаблон недели',`<p class="muted">Сохраните интервалы открытой недели как шаблон. При применении задачи и существующие интервалы сохраняются; точные дубликаты не добавляются.</p><p>Открытая неделя: <strong>${dateFmt(week)} — ${dateFmt(addDays(week,6))}</strong></p><p class="muted">В шаблоне ${state.template.length} интервалов.</p><div class="actions">${btn('Отмена','close')}${btn('Сохранить эту неделю','template-save')}${btn('Применить к этой неделе','template-apply','','primary')}</div>`);}
function showMove(id){const t=findTask(state,id);if(!t.category){placementForm(id);return;}modal(t.date?'Перенести задачу':'Назначить дату',`<p>${esc(t.title)}</p><form id="move-form" data-id="${id}">${field('Новая дата',input('date','date',t.date?addDays(t.date,1):dateKey(),'required'))}<p class="muted small">После переноса задача появится в своём вагончике. Если места нет, она будет видна в накопителе.</p>${actions('<button class="primary">Перенести</button>')}</form>`);}
function showAdjust(){const dates=Array.from({length:7},(_,i)=>addDays(week,i));const problems=[];for(const d of dates)for(const c of state.categories){const l=load(state,c.id,d);if(l.overflow>0)problems.push(`<div class="panel"><h3>${esc(c.name)} · ${dateFmt(d)}</h3><p class="warn">Не помещается ${Math.ceil(l.overflow)} мин</p>${state.tasks.filter(t=>t.date===d&&t.category===c.id&&!t.done).map(t=>`<div class="row"><span>${esc(t.title)} · ${Math.ceil(Math.max(0,t.estimate-t.actual))} мин осталось</span>${btn('Перенести','move',`data-id="${t.id}"`)}</div>`).join('')}${slotsOn(state,d).filter(s=>s.category===c.id).map(s=>btn('Изменить интервал','slot',`data-id="${s.id}" data-date="${d}"`)).join('')}</div>`);}const collisions=conflicts(state).filter(x=>state.slots.some(s=>s.id===x.slot&&dates.includes(s.date)));modal('Корректировка недели',(collisions.length?`<div class="notice">${collisions.map(x=>esc(x.text)).join('<br>')}</div>`:'')+(problems.join('')||'<p class="muted">Перегрузки задач нет. Все дела помещаются в свои вагончики.</p>')+`<div class="actions">${btn('Закрыть','close')}</div>`);}
function accrued(timer){return timer.elapsed+(timer.running?(Date.now()-timer.started)/1000:0);}
function updateClock(){const t=state.timer;if($('#clock')){const seconds=t?Math.max(0,Math.ceil(1500-accrued(t))):1500;$('#clock').textContent=`${Math.floor(seconds/60).toString().padStart(2,'0')}:${(seconds%60).toString().padStart(2,'0')}`;if(t&&$('#timer-status'))$('#timer-status').textContent=t.running?'Фокус-сессия идёт':'Пауза';}}
function startFocus(id){if(state.timer){toast('Сначала завершите текущую сессию.');return;}const t=state.tasks.find(x=>x.id===id),slot=slotsOn(state,t.date).filter(s=>s.category===t.category);if(!slot.length){toast('Добавьте интервал для вагончика этой задачи.');return;}if(t.date!==dateKey()){toast('Таймер доступен для задач сегодняшнего дня.');return;}if(!state.baselines[t.date]&&(conflicts(state).some(x=>slotsOn(state,t.date).some(s=>s.id===x.slot))||state.categories.some(c=>load(state,c.id,t.date).overflow>0))){toast('Сначала скорректируйте план дня: есть перегрузка или пересечения.');return;}snapshotDay(state,t.date);state.timer={task:id,date:t.date,category:t.category,elapsed:0,started:Date.now(),running:true,estimateWarned:false,blockWarned:false};save();view='day';day=t.date;render();}
function stopSession(message=true){const timer=state.timer;if(!timer)return;const elapsed=accrued(timer)/60,t=state.tasks.find(x=>x.id===timer.task);if(elapsed>0){t.actual+=elapsed;state.sessions.push({id:uid(),task:t.id,category:t.category,date:timer.date,minutes:elapsed,at:Date.now()});}state.timer=null;save();render();if(message)modal('Сессия завершена',`<p>${esc(t.title)} · ${Math.round(elapsed)} мин фокуса.</p><p class="muted">Можно сделать перерыв или продолжить работу новой сессией.</p><div class="actions">${btn('Закрыть','close')}${btn('Задача готова','complete',`data-id="${t.id}"`,'primary')}</div>`);}
function pauseTimer(){const t=state.timer;if(t?.running){t.elapsed=accrued(t);t.running=false;save();}updateClock();}
function inspectTimer(){const timer=state.timer;if(!timer?.running)return;const task=state.tasks.find(t=>t.id===timer.task),extra=accrued(timer)/60,l=load(state,task.category,timer.date),now=new Date(),nowMin=now.getHours()*60+now.getMinutes(),ss=slotsOn(state,timer.date).filter(s=>s.category===task.category),lastEnd=Math.max(...ss.map(s=>minutes(s.start)+s.duration));const outside=timer.date!==dateKey()||!ss.some(s=>nowMin>=minutes(s.start)&&nowMin<minutes(s.start)+s.duration);
if(!timer.blockWarned&&(l.actual+extra>=l.budget||outside)){timer.blockWarned=true;pauseTimer();const affected=state.tasks.filter(t=>t.date===timer.date&&!t.done&&t.id!==task.id);modal('Время вагончика закончилось',`<div class="notice">Таймер приостановлен. Продолжение меняет план дня — сначала пересмотрите оставшиеся задачи.</div><p>Оставшиеся задачи всех вагончиков:</p>${affected.map(t=>`<div class="row"><span>${esc(cat(t.category).name)} · ${esc(t.title)}</span>${btn('Перенести','move',`data-id="${t.id}"`)}</div>`).join('')||'<p class="muted">Других незавершённых задач сегодня нет.</p>'}<p class="small muted">Для продолжения увеличьте интервал в неделе, устраните пересечения и перезапустите сессию.</p><div class="actions">${btn('Завершить сессию','timer-stop','','primary')}</div>`);return;}
if(!timer.estimateWarned&&task.actual+extra>=task.estimate){timer.estimateWarned=true;pauseTimer();modal('Оценённое время задачи истекло',`<p>${esc(task.title)}</p><p class="muted">Можно оставить остальные задачи в плане и продолжить до конца вагончика или перенести часть дел.</p>${state.tasks.filter(t=>t.date===timer.date&&t.category===task.category&&!t.done&&t.id!==task.id).map(t=>`<div class="row"><span>${esc(t.title)}</span>${btn('Перенести','move',`data-id="${t.id}"`)}</div>`).join('')}<div class="actions">${btn('Завершить сессию','timer-stop')}${btn('Оставить план и продолжить','timer-toggle','','primary')}</div>`);return;}
if(accrued(timer)>=1500){pauseTimer();stopSession();}}
$('#app').addEventListener('click',handle);$('#modal').addEventListener('click',handle);$('#toast').addEventListener('click',handle);
function handle(e){const b=e.target.closest('[data-action]');if(!b)return;const {action:a,id,date}=b.dataset;
if(['coach-detail','busy-detail','slot'].includes(a)&&Date.now()<suppressCoachClickUntil)return;if(a==='open-connections'){view='settings';render();fetchTelegram();fetchCalendar();return;}if(a==='calendar-connect'){showCalendarConnect();return;}if(a==='calendar-sync'){syncCalendar(true);return;}if(a==='calendar-disconnect'){disconnectCalendar();return;}if(a==='task-duration'){const t=findTask(state,id);if(!t)return;const delta=Number(b.dataset.delta);if(![-15,15].includes(delta))return;t.estimate=Math.max(1,Math.min(1440,t.estimate+delta));const detail=$('[data-coach-details]')?.dataset.coachDetails;save();render();if(detail&&$('#modal').open)showCoachDetails(detail);return;}if(a==='busy-detail'){showCalendarEvent(id);return;}if(a==='coach-detail'){showCoachDetails(id);return;}if(a==='coach-task'){showCoachDetails(id);$('#coach-task-form input[name=title]')?.focus();return;}if(a==='timeline-add'){if(!canSchedule(date,b.dataset.start)){toast('Это время уже прошло.');return;}showSlot(undefined,date);$('#modal input[name=start]').value=b.dataset.start;return;}if(a==='toggle-task'){const t=findTask(state,id);if(t){if(state.timer?.task===id)stopSession(false);t.done=!t.done;const detail=$('[data-coach-details]')?.dataset.coachDetails;save();render();if(detail&&$('#modal').open)showCoachDetails(detail);}return;}if(a==='palette-category'){if(Date.now()<suppressPaletteClickUntil)return;showSlot(undefined,defaultPaletteDate(),id,120);return;}if(a==='palette-busy'){if(Date.now()<suppressPaletteClickUntil)return;showUnavailable(defaultPaletteDate(),60);return;}if(a==='place-open'){placementForm(id);return;}if(a==='place-confirm'){proposePlacement(id,b.dataset.slot,true);return;}if(a==='delete-task'){removeTask(id);return;}if(a==='undo-delete'){undoDeletion();return;}if(a==='stash-task'){sendToBacklog(id);return;}if(a==='open-backlog'){view='backlog';render();return;}if(a==='wizard-backlog'){wizard.date=null;wizard.step=4;showWizard();return;}if(a==='refresh-plan'){refreshRemotePlan(true);return;}if(a==='open-inbox'){view='backlog';inboxPeriod='all';inboxReason='all';render();refreshRemotePlan();return;}if(a==='inbox-period'){inboxPeriod=b.dataset.period;render();return;}if(a==='inbox-reason'){inboxReason=b.dataset.reason;render();return;}if(a==='schedule-task'){const task=findTask(state,id);if(task)showSlot(undefined,task.date||dateKey(),task.category,Math.max(15,Math.min(1440,Math.ceil(Math.max(0,task.estimate-task.actual)/15)*15)));return;}if(a==='inbox-block'){const task=state.tasks.find(t=>t.id===id);if(task){selectedCategory=task.category;blockFilter='all';view='blocks';render();}return;}if(a==='telegram-connect'){showTelegramConnect();return;}if(a==='telegram-link'){telegramLink();return;}if(a==='telegram-disconnect'){modal('Отключить бота?',`<p>Бот перестанет добавлять задачи в этот аккаунт. Существующие задачи сохранятся.</p><div class="actions">${btn('Отмена','close')}${btn('Отключить','telegram-disconnect-confirm','','danger')}</div>`);return;}if(a==='telegram-disconnect-confirm'){disconnectTelegram();return;}if(a==='auth-mode'){authMode=b.dataset.mode;renderAuth();return;}if(a==='auth-retry'){boot();return;}if(a==='logout'){logout();return;}if(a==='migrate-plan'){migrateLegacy();return;}if(a==='reload-plan'){location.reload();return;}if(a==='retry-sync'){flushPlan();return;}if(a==='open-block'){selectedCategory=id;blockFilter='week';view='blocks';render();return;}if(a==='block-filter'){blockFilter=b.dataset.filter;render();return;}if(a==='block-select'){selectedCategory=id;render();return;}if(a==='close')return close();if(a==='nav'){view=b.dataset.view;render();if(view==='settings'){fetchTelegram();fetchCalendar();}refreshRemotePlan();}if(a==='week-prev'){week=addDays(week,-7);render();syncCalendar(false);}if(a==='week-next'){week=addDays(week,7);render();syncCalendar(false);}if(a==='week-now'){week=monday(dateKey());render();syncCalendar(false);}if(a==='task')showTask();if(a==='slot')showSlot(id,date);if(a==='category')showCategory(id,b.dataset.color);if(a==='unavailable')showUnavailable();if(a==='adjust')showAdjust();if(a==='move')showMove(id);if(a==='template')showTemplate();
if(a==='delete-slot'){state.slots=state.slots.filter(s=>s.id!==id);save();close();render();}if(a==='delete-event'){if(state.unavailable.find(e=>e.id===id)?.source==='google'){state.calendarHiddenIds=[...new Set([...(state.calendarHiddenIds||[]),id])];}state.unavailable=state.unavailable.filter(s=>s.id!==id);save();if($('#modal').open)close();render();}
if(a==='template-save'){state.template=state.slots.filter(s=>s.date>=week&&s.date<=addDays(week,6)).map(({category,start,duration,date})=>({category,start,duration,weekday:(new Date(date+'T12:00:00').getDay()+6)%7}));save();close();toast('Шаблон сохранён');}
if(a==='template-apply'){const proposed=state.template.map(t=>({...t,id:uid(),date:addDays(week,t.weekday)})).filter(t=>canSchedule(t.date,t.start)).filter(t=>!state.slots.some(s=>s.date===t.date&&s.start===t.start&&s.category===t.category&&s.duration===t.duration));const merged={...state,slots:[...state.slots,...proposed]};if(conflicts(merged).length>conflicts(state).length){toast('Шаблон создаёт пересечения. Сначала измените интервалы или события.');return;}state.slots.push(...proposed);save();close();render();toast('Шаблон применён');}
if(a==='wizard-cat'){wizard.category=id||null;wizard.step=2;showWizard();}if(a==='wizard-duration'){wizard.estimate=+b.dataset.minutes;wizard.step=wizard.date===null?4:3;showWizard();}if(a==='wizard-date'){wizard.date=date;wizard.step=4;showWizard();}if(a==='wizard-back'){wizard.step--;showWizard();}if(a==='wizard-reset'){wizard.step=0;showWizard();}if(a==='wizard-save'){const target=state.slots.find(s=>s.id===wizard.slotId);if(target&&!canPlaceInSlot(target)){toast('Время этого вагончика уже прошло. Выберите будущий вагончик.');return;}if(wizard.date===dateKey()&&state.slots.some(s=>s.date===wizard.date&&s.category===wizard.category)&&!state.slots.some(s=>s.date===wizard.date&&s.category===wizard.category&&canPlaceInSlot(s))){toast('Все вагончики этого вагончика на сегодня закончились. Выберите будущую дату или накопитель.');return;}if(wizard.date&&wizard.date<dateKey()){toast('Выберите сегодняшний или будущий день.');return;}const task={id:uid(),title:wizard.title,category:wizard.category,estimate:wizard.estimate,date:wizard.date,originalDate:wizard.date,slotId:state.slots.find(s=>s.id===wizard.slotId&&s.date===wizard.date&&s.category===wizard.category&&canPlaceInSlot(s))?.id||state.slots.find(s=>s.date===wizard.date&&s.category===wizard.category&&canPlaceInSlot(s))?.id,actual:0,done:false,createdAt:Date.now()};scheduleNewTask(state,task);(wizard.date===null?(state.backlog ||= []):state.tasks).push(task);save();close();render();toast('Задача добавлена');}
if(a==='start-day'){if(day!==dateKey()){toast('Запустить можно сегодняшний день.');return;}const issues=conflicts(state).filter(x=>slotsOn(state,day).some(s=>s.id===x.slot));const overloaded=state.categories.some(c=>load(state,c.id,day).overflow>0);if(issues.length||overloaded){toast('Сначала устраните пересечения и перегрузку в корректировке недели.');return;}snapshotDay(state,day);save();render();}
if(a==='focus')startFocus(id);if(a==='timer-stop'){close();stopSession();}if(a==='timer-toggle'){const t=state.timer;if(!t)return;if(t.blockWarned){toast('Время вагончика закончилось. Завершите сессию и скорректируйте интервалы.');return;}if(t.running)pauseTimer();else{t.running=true;t.started=Date.now();save();}if($('#modal').open)close();render();}
if(a==='complete'){const t=state.tasks.find(t=>t.id===id);if(state.timer?.task===id)stopSession(false);t.done=true;save();if($('#modal').open)close();render();}
if(a==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`rhythm-${dateKey()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}if(a==='import')$('#import-file').click();}
document.addEventListener('change',async e=>{if(e.target.id==='selected-day'){day=e.target.value||dateKey();render();}if(e.target.id==='import-file'){const f=e.target.files[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!validImport(data))throw Error('Неверный формат');modal('Импорт резервной копии',`<p>Заменить текущие данные? В копии ${data.tasks.length} задач. Сначала экспортируйте текущий план, если хотите сохранить его.</p>${actions(btn('Заменить данные','confirm-import','','primary'))}`);const b=$('[data-action="confirm-import"]');b.onclick=()=>{state=data;state.timer=null;save();close();render();toast('Данные восстановлены');};}catch{toast('Не удалось импортировать файл: неверный формат данных.');}}});
function validImport(d){
 const id=v=>typeof v==='string'&&/^[a-z0-9_-]+$/i.test(v),text=v=>typeof v==='string',date=v=>text(v)&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(new Date(v+'T12:00:00').getTime()),time=v=>text(v)&&/^([01]\d|2[0-3]):[0-5]\d$/.test(v),num=v=>Number.isFinite(v)&&v>=0,duration=v=>num(v)&&v>0&&v<=1440;
 if(d?.version!==1||!['categories','slots','tasks','template','unavailable','moves','sessions'].every(k=>Array.isArray(d[k]))||!d.baselines||Array.isArray(d.baselines)||!d.reviews||Array.isArray(d.reviews))return false;
 const ref=v=>d.categories.some(c=>c.id===v),interval=s=>ref(s.category)&&time(s.start)&&duration(s.duration)&&minutes(s.start)+s.duration<=1440;
 return new Set(d.categories.map(c=>c.id)).size===d.categories.length&&d.categories.every(c=>id(c.id)&&text(c.name)&&text(c.tag)&&/^#[0-9a-f]{6}$/i.test(c.color))&&d.slots.every(s=>id(s.id)&&date(s.date)&&interval(s))&&d.template.every(s=>interval(s)&&Number.isInteger(s.weekday)&&s.weekday>=0&&s.weekday<=6)&&d.tasks.every(t=>id(t.id)&&text(t.title)&&date(t.date)&&duration(t.estimate)&&num(t.actual)&&typeof t.done==='boolean'&&ref(t.category))&&(d.backlog===undefined||Array.isArray(d.backlog)&&d.backlog.every(t=>id(t.id)&&text(t.title)&&t.date===null&&duration(t.estimate)&&num(t.actual)&&typeof t.done==='boolean'&&(t.category===null||ref(t.category))))&&d.unavailable.every(s=>id(s.id)&&text(s.title)&&date(s.from)&&(!s.until||date(s.until))&&['once','weekly'].includes(s.repeat)&&Number.isInteger(s.weekday)&&s.weekday>=0&&s.weekday<=6&&time(s.start)&&duration(s.duration))&&d.moves.every(m=>id(m.id)&&id(m.task)&&text(m.title)&&(date(m.from)||m.from===null&&m.source==='backlog')&&(date(m.to)||m.to===null&&m.target==='backlog')&&num(m.minutes))&&d.sessions.every(s=>id(s.id)&&id(s.task)&&ref(s.category)&&date(s.date)&&num(s.minutes))&&Object.entries(d.baselines).every(([k,b])=>date(k)&&Array.isArray(b.tasks)&&b.tasks.every(t=>id(t.id)&&ref(t.category)&&text(t.title)&&duration(t.estimate)))&&Object.entries(d.reviews).every(([k,r])=>date(k)&&r&&typeof r==='object'&&r.ratings&&typeof r.ratings==='object'&&text(r.reason)&&text(r.comment));
}
document.addEventListener('submit',e=>{const f=e.target;if(!f.id)return;e.preventDefault();const d=Object.fromEntries(new FormData(f));
if(f.id==='quick-backlog-form'){if(d.category&&!state.categories.some(c=>c.id===d.category)){showCategory();toast('Сначала назовите свой вагончик.');return;}if(!d.title.trim())return;(state.backlog ||= []).push({id:uid(),title:d.title.trim(),category:d.category||null,estimate:+d.estimate,date:null,originalDate:null,actual:0,done:false,createdAt:Date.now()});save();render();toast('Дело добавлено в накопитель');return;}if(f.id==='wizard-title'){if(!d.title.trim())return;wizard.title=d.title.trim();wizard.step=1;showWizard();}
if(f.id==='wizard-custom'){wizard.estimate=+d.estimate;wizard.step=wizard.date===null?4:3;showWizard();}if(f.id==='wizard-calendar'){wizard.date=d.date;wizard.step=4;showWizard();}
if(f.id==='slot-form'){const duration=+d.duration;const old=state.slots.find(s=>s.id===f.dataset.id);if(!canSchedule(d.date,d.start)&&!(old&&old.date===d.date&&old.start===d.start&&old.category===d.category&&old.duration>=duration&&minutes(d.start)+duration>pastMinutes(d.date))){toast('В прошедшее время нельзя добавить или перенести вагончик.');return;}if(minutes(d.start)+duration>1440){toast('Интервал должен заканчиваться в этот же день.');return;}const slot={id:f.dataset.id||uid(),category:d.category,date:d.date,start:d.start,duration};const others=state.slots.filter(s=>s.id!==slot.id&&s.date===slot.date);if(others.some(s=>overlap(s,slot))||state.unavailable.some(s=>unavailableOn(s,slot.date)&&overlap(s,slot))){toast('Есть пересечение с другим интервалом или недоступным временем.');return;}state.slots=state.slots.filter(s=>s.id!==slot.id);state.slots.push(slot);save();close();render();}
if(f.id==='category-form'){if(!d.name.trim())return;if(state.categories.some(c=>c.id!==f.dataset.id&&c.tag.toLowerCase()===d.tag.toLowerCase())){toast('Этот тег уже используется другим вагончиком.');return;}const c={id:f.dataset.id||uid(),name:d.name.trim(),tag:d.tag,color:d.color};state.categories=state.categories.filter(x=>x.id!==c.id);state.categories.push(c);save();close();render();}
if(f.id==='event-form'){if(!canSchedule(d.from,d.start)){toast('В прошедшее время нельзя добавить событие.');return;}if(d.until&&d.until<d.from){toast('Конец периода раньше начала.');return;}if(minutes(d.start)+Number(d.duration)>1440){toast('Событие должно заканчиваться в тот же день.');return;}state.unavailable.push({id:uid(),...d,weekday:+d.weekday,duration:+d.duration});save();close();render();toast('Событие добавлено. Пересечения отмечены в неделе.');}
if(f.id==='move-form'){if(d.date<dateKey()){toast('Нельзя перенести задачу в прошедший день.');return;}const moving=findTask(state,f.dataset.id);if(d.date===dateKey()&&state.slots.some(s=>s.date===d.date&&s.category===moving.category)&&!state.slots.some(s=>s.date===d.date&&s.category===moving.category&&canPlaceInSlot(s))){toast('Вагончики этого вагончика на сегодня уже закончились. Выберите другую дату.');return;}moveTask(state,f.dataset.id,d.date);scheduleNewTask(state,moving);save();close();render();toast('Задача перенесена. Проверьте нагрузку нового дня.');}
if(f.id==='review-form'){state.reviews[day]={ratings:Object.fromEntries(state.categories.map(c=>[c.id,d['rating-'+c.id]])),reason:d.reason,comment:d.comment};save();toast('Итоги сохранены');}});
window.addEventListener('storage',e=>{if(e.key===KEY&&account){syncBlocked=true;toast('План изменён в другой вкладке. Обновите эту страницу перед продолжением.');}});
setInterval(()=>{if(account){updateClock();inspectTimer();}},1000);boot();

async function requestAPI(path,options={}){const r=await fetch(API_BASE+path,{credentials:API_BASE?'omit':'same-origin',...options,headers:{'Content-Type':'application/json',...(sessionToken?{Authorization:'Bearer '+sessionToken}:{}),...options.headers}});let data;try{data=await r.json();}catch{throw new Error('Сервер недоступен. Попробуйте позже.');}if(!r.ok){const error=new Error(data.error||'Не удалось выполнить запрос.');error.status=r.status;throw error;}if(API_BASE&&data.token){sessionToken=data.token;try{sessionStorage.setItem('paravoziki.session',sessionToken);}catch{}}return data;}
function renderAuth(error=''){const register=authMode==='register';$('#app').innerHTML=`<div class="auth-page"><div class="auth-card"><div class="brand"><img src="logo.svg" width="55" height="48" alt=""><span>паровозики</span></div><img class="auth-train" src="train.svg" alt=""><h1>${register?'Создать аккаунт':'Войти в аккаунт'}</h1><p class="muted">Ваши вагончики, задачи и время — в одном месте.</p><div class="actions auth-tabs">${btn('Вход','auth-mode','data-mode="login"',register?'':'primary')}${btn('Регистрация','auth-mode','data-mode="register"',register?'primary':'')}</div>${error?`<p class="notice" role="alert">${esc(error)}</p>`:''}<form id="auth-form">${field('Email',input('email','email','','required autocomplete="username" maxlength="254"'))}${field('Пароль',input('password','password','','required minlength="12" maxlength="72" autocomplete="'+(register?'new-password':'current-password')+'"'))}${register?field('Повторите пароль',input('confirmation','password','','required minlength="12" autocomplete="new-password"')):''}<p class="small muted">${register?'От 12 символов. Сохраните пароль в менеджере паролей. Подтверждение email и сброс пароля пока недоступны.':'Введите email и пароль от своего аккаунта.'}</p><button class="primary auth-submit">${register?'Создать аккаунт':'Войти'}</button></form></div></div>`;}
async function boot(){ $('#app').innerHTML='<div class="auth-page"><p class="muted" role="status">Загружаем ваш план…</p></div>';try{const result=await requestAPI('/api/auth/me');if(result.user)await openAccount(result.user);else renderAuth();}catch(e){$('#app').innerHTML=`<div class="auth-page"><section class="panel"><h2>Не удалось подключиться</h2><p>${esc(e.message)}</p>${btn('Повторить','auth-retry','','primary')}</section></div>`;}}
async function openAccount(user){telegramConnection=null;calendarConnection=null;remoteRevision=0;lastDeletion=null;KEY='paravoziki.account.'+user.id;const result=await requestAPI('/api/plan');account=user;view='week';week=monday(dateKey());day=dateKey();selectedCategory=null;pendingPlan=null;revision=result.revision;state=result.state||emptyPlan();let cached;try{cached=JSON.parse(localStorage.getItem(KEY));}catch{}if(cached?.dirty&&cached.revision===revision&&validImport(cached.state)){state=cached.state;pendingPlan=structuredClone(state);}else if(cached?.dirty){localStorage.setItem(KEY+'.unsaved',JSON.stringify(cached));toast('Несохранённая локальная копия оставлена как резервная. Загружен серверный план.');}syncBlocked=false;render();if(pendingPlan)flushPlan();fetchCalendar(true);}
function migrateLegacy(){try{const legacy=JSON.parse(localStorage.getItem('rhythm.v1'));if(!validImport(legacy))throw Error();state=legacy;state.timer=null;close();save();render();toast('План перенесён в аккаунт');}catch{toast('Не удалось прочитать прежний план. Используйте импорт JSON.');}}
async function flushPlan(){if(!account||syncBusy||syncBlocked||!pendingPlan)return;syncBusy=true;try{while(pendingPlan&&!syncBlocked){const plan=pendingPlan;pendingPlan=null;try{const result=await requestAPI('/api/plan',{method:'PUT',body:JSON.stringify({state:plan,revision})});revision=result.revision;cachePlan(!!pendingPlan);if($('#sync-status'))$('#sync-status').textContent='Все изменения сохранены';}catch(e){pendingPlan=pendingPlan||plan;cachePlan(true);if(e.status===409){syncBlocked=true;pauseTimer();modal('План изменён на другом устройстве',`<p>Сначала сохраните свою текущую версию через экспорт, затем загрузите актуальный план. Данные на сервере не были перезаписаны.</p><div class="actions">${btn('Экспорт моей версии','export')}${btn('Загрузить актуальный план','reload-plan','','primary')}</div>`);}else{if($('#sync-status'))$('#sync-status').innerHTML=btn('Повторить сохранение','retry-sync','','small');toast(e.message+' Локальная копия сохранена.');}break;}}}finally{syncBusy=false;}}
async function logout(){pauseTimer();await flushPlan();if(pendingPlan||syncBusy){toast('Сначала сохраните изменения или экспортируйте резервную копию.');return;}try{await requestAPI('/api/auth/logout',{method:'POST',body:'{}'});account=null;sessionToken='';try{sessionStorage.removeItem('paravoziki.session');}catch{}state=emptyPlan();revision=0;pendingPlan=null;close();renderAuth();}catch(e){toast(e.message);}}
document.addEventListener('submit',async e=>{if(e.target.id!=='auth-form')return;e.preventDefault();const form=e.target,values=Object.fromEntries(new FormData(form)),submit=form.querySelector('button');if(authMode==='register'&&values.password!==values.confirmation){renderAuth('Пароли не совпадают.');return;}submit.disabled=true;submit.textContent='Подождите…';try{const result=await requestAPI('/api/auth/'+authMode,{method:'POST',body:JSON.stringify({email:values.email,password:values.password})});await openAccount(result.user);}catch(error){account=null;renderAuth(error.message);}});

function telegramPanel(){const c=telegramConnection;return `<section class="panel"><h2>Telegram</h2>${c?.connected?`<span class="pill">${c.linked?'Чат привязан':'Ожидает привязки чата'}</span><p><strong>@${esc(c.username)}</strong></p><p class="muted small">Напишите задачу боту: он предложит вагончик и длительность и сохранит дело в накопитель. Дела без места в расписании видны в накопителе. Новые задачи подгружаются автоматически; при необходимости нажмите ↻ рядом со статистикой накопителя.</p>${c.linkUrl?`<div class="notice"><a href="${esc(c.linkUrl)}" target="_blank" rel="noopener noreferrer">Открыть бота и привязать мой чат →</a><p class="small">Ссылка действует 10 минут. В Telegram нажмите «Начать» / Start. Не передавайте эту ссылку другим людям.</p></div>`:''}<div class="actions">${btn(c.linked?'Новая ссылка привязки':'Получить ссылку привязки','telegram-link','','primary')}${btn('Отключить','telegram-disconnect','','small')}</div>`:`<p class="muted">Подключите своего бота из BotFather. Он будет добавлять задачи в ваш личный план через кнопки.</p><p class="small muted">Токен вводится только здесь и хранится на сервере в зашифрованном виде.</p>${btn('Подключить Telegram-бота','telegram-connect','','primary')}`}</section>`;}
async function fetchTelegram(){if(!account)return;try{const userId=account.id;const connection=await requestAPI('/api/telegram/status');if(account?.id!==userId)return;telegramConnection=connection;if(view==='settings')render();}catch(e){toast(e.message);}}
function showTelegramConnect(){modal('Подключить Telegram-бота',`<form id="telegram-form"><p class="muted">Вставьте токен из BotFather. Он не попадёт в GitHub, экспорт плана или браузерное хранилище.</p>${field('Токен бота',input('token','password','','required autocomplete="off" spellcheck="false" placeholder="Токен из BotFather"'))}<p class="small muted">Этот бот должен использоваться только для «Паровозиков»: подключение заменит его прежний webhook.</p>${actions('<button class="primary">Подключить</button>')}</form>`);}
async function telegramLink(){try{telegramConnection=await requestAPI('/api/telegram/link',{method:'POST',body:'{}'});render();}catch(e){toast(e.message);}}
async function disconnectTelegram(){try{telegramConnection=await requestAPI('/api/telegram/disconnect',{method:'POST',body:'{}'});close();render();}catch(e){toast(e.message);}}
document.addEventListener('submit',async e=>{if(e.target.id!=='telegram-form')return;e.preventDefault();const form=e.target,token=new FormData(form).get('token').trim(),button=form.querySelector('button.primary');button.disabled=true;button.textContent='Подключаем…';try{if(revision===0){save();await flushPlan();}if(pendingPlan||syncBusy||syncBlocked)throw Error('Сначала дождитесь сохранения плана или устраните конфликт.');telegramConnection=await requestAPI('/api/telegram/connect',{method:'POST',body:JSON.stringify({token})});form.reset();close();$('#modal').innerHTML='';render();toast('Бот подключён. Откройте ссылку, чтобы привязать чат.');}catch(error){button.disabled=false;button.textContent='Подключить';toast(error.message);}});

function updateRemoteNotice(){const target=$('#remote-notice');if(!target)return;target.innerHTML=remoteRevision>revision?`<div class="notice">В плане появились изменения, в том числе из Telegram. ${btn('Загрузить изменения','refresh-plan')}</div>`:'';}
async function refreshRemotePlan(manual=false){
 if(!account||remoteBusy||coachGesture||draggedEntity)return;
 if(pendingPlan||syncBusy||syncBlocked){if(manual)toast('Сначала сохраните текущие изменения. При конфликте экспортируйте свою версию и загрузите актуальный план.');return;}
 if(manual&&state.timer){toast('Чтобы обновить план без потери учёта времени, сначала завершите текущую фокус-сессию.');return;}
 remoteBusy=true;const userId=account.id,startedRevision=revision;
 try{
  const meta=manual?null:await requestAPI('/api/plan/version');
  if(!account||account.id!==userId||revision!==startedRevision)return;
  if(meta&&meta.revision<=revision)return;
  if(meta){remoteRevision=meta.revision;updateRemoteNotice();}
  const canApply=manual||(['week','blocks','inbox','backlog'].includes(view)&&!$('#modal').open&&!state.timer);
  if(!canApply||pendingPlan||syncBusy||syncBlocked)return;
  const result=await requestAPI('/api/plan');
  if(!account||account.id!==userId||revision!==startedRevision||pendingPlan||syncBusy||syncBlocked||state.timer||(!manual&&$('#modal').open))return;
  if(result.revision>revision&&result.state){state=result.state;revision=result.revision;remoteRevision=0;cachePlan(false);render();if(manual)toast('Задачи обновлены');}
  else if(manual)toast('План уже актуален');
 }catch(error){if(manual)toast(error.message);}finally{remoteBusy=false;}
}
setInterval(()=>{if(!document.hidden)refreshRemotePlan();},15000);
window.addEventListener('focus',()=>refreshRemotePlan());
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshRemotePlan();});

function navLabel(id,title){const count=id==='backlog'?backlogTasks(state).length:null;return title+(count===null?'':` <span class="inbox-count">${count}</span>`);}
function wagonText(color){const c=color.slice(1).match(/../g)?.map(v=>parseInt(v,16)/255)||[.5,.5,.5],l=c.map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4),lum=.2126*l[0]+.7152*l[1]+.0722*l[2];return (lum+.05)/.065>1.05/(lum+.05)?'#15251a':'#ffffff';}
function renderWagonYard(){return `<section class="wagon-yard" aria-label="Запас вагончиков"><h2>Запас вагончиков</h2><p>Перетащите вагончик в день недели или нажмите на него. Их можно использовать сколько угодно раз. Время и длительность выбираются после переноса.</p><div class="yard-track"><img class="yard-engine" src="logo.svg" alt=""><div class="yard-wagons">${state.categories.map(c=>`<div role="button" tabindex="0" class="wagon" draggable="true" data-drag-kind="category" data-category="${c.id}" data-action="palette-category" data-id="${c.id}" style="--wagon:${c.color};--wagon-text:${wagonText(c.color)}" aria-label="Добавить вагончик ${esc(c.name)}"><strong>${esc(c.name)}</strong><span>2 часа</span></div>`).join('')}<div role="button" tabindex="0" class="wagon wagon-busy" draggable="true" data-drag-kind="busy" data-action="palette-busy" style="--wagon:#a7aaa2;--wagon-text:#15251a" aria-label="Добавить занятое время">${state.categories.length?'<strong>Занятое время</strong><span>1 час · с подписью</span>':'<span aria-hidden="true">＋</span>'}</div></div></div></section>`;}
function taskIsPlaced(t){return !!t.date&&!inboxTasks(state).some(x=>x.task.id===t.id)&&state.slots.some(slot=>tasksInSlot(state,slot).some(x=>x.id===t.id));}
function taskCheck(t){return t.date?btn(t.done?'✓':'','toggle-task',`data-id="${t.id}" role="checkbox" aria-checked="${!!t.done}" aria-label="${t.done?'Снять отметку сделано':'Отметить сделано'}: ${esc(t.title)}" title="${t.done?'Снять отметку':'Сделано'}"`,'task-check '+(t.done?'is-checked':'')):'';}
function taskDelete(t){return btn('×','delete-task',`data-id="${t.id}" aria-label="Удалить задачу: ${esc(t.title)}" title="Удалить задачу"`,'icon-button task-delete');}
function taskControls(t,compact=false,deleteAlreadyShown=false){return (!t.done&&!taskIsPlaced(t)?btn('→','place-open',`data-id="${t.id}" aria-label="Поместить задачу в вагончик: ${esc(t.title)}" title="В вагончик"`,'icon-button task-place'):'')+(compact?'':btn(t.date?'↓':'▦',t.date?'stash-task':'move',`data-id="${t.id}" aria-label="${t.date?'В накопитель':'Назначить дату'}: ${esc(t.title)}" title="${t.date?'В накопитель':'Назначить дату'}"`,'icon-button task-secondary'))+(compact||deleteAlreadyShown?'':taskDelete(t));}
function compactTask(t){return `<div class="task-mini compact-task-card" style="--color:${cat(t.category).color}" draggable="${!t.done}" data-drag-kind="task" data-task-id="${t.id}"><div class="dense-task-header">${taskCheck(t)}${taskDurationControl(t)}<span class="task-category-label" title="${esc(cat(t.category).name)}">${esc(cat(t.category).name)}</span>${taskDelete(t)}</div><div class="dense-task-content"><div class="task-title ${t.done?'done':''}">${esc(t.title)}</div>${!t.done&&!taskIsPlaced(t)?taskControls(t,true):''}</div></div>`;}

function quickBacklogForm(){return `<form id="quick-backlog-form" class="quick-backlog-form">${field('Новое дело',input('title','text','','required maxlength="240" placeholder="Что нужно сделать?"'))}${field('Вагончик',select('category',[['','Без вагончика'],...state.categories.map(c=>[c.id,c.name])],''))}${field('Минуты',input('estimate','number',30,'required min="1" max="1440"'))}<button class="primary" type="submit">В накопитель</button></form>`;}
function renderBacklogCounters(){const counts=backlogCounts(state);return `<section class="backlog-counts" aria-label="Неразобранные дела"><div class="backlog-counter-heading"><span>Неразобранные дела</span>${btn('↻','refresh-plan','aria-label="Обновить задачи" title="Обновить задачи"','icon-button backlog-counter-refresh')}</div><div class="backlog-count-train"><div class="backlog-count-engine" aria-label="Всего неразобранных дел: ${counts.total}" title="Все неразобранные дела"><strong>${counts.total}</strong></div>${state.categories.map(c=>`<div class="backlog-count-unit"><span class="backlog-count-wagon ${counts.byCategory[c.id]?'':'zero-count'}" style="--counter-color:${c.color}" title="${esc(c.name)}: ${counts.byCategory[c.id]}" aria-label="${esc(c.name)}: ${counts.byCategory[c.id]} неразобранных дел">${counts.byCategory[c.id]}</span><small title="${esc(c.name)}">${esc(c.name)}</small></div>`).join('')}<div class="backlog-count-unit"><span class="backlog-count-wagon unassigned-count" title="Без вагончика: ${counts.unassigned}" aria-label="Без вагончика: ${counts.unassigned}">${counts.unassigned}</span><small>Без вагона</small></div></div></section>`;}
function renderBacklogTray(){const tasks=backlogTasks(state);return `<details class="backlog-tray" open><summary>Накопитель</summary><p class="muted">Перетащите дело в вагончик или нажмите →.</p><div class="backlog-chips">${tasks.map(t=>`<article style="--color:${cat(t.category).color}">${compactTask(t)}</article>`).join('')||'<p class="muted">Неразобранных дел пока нет.</p>'}</div>${btn('Открыть накопитель','open-backlog')}</details>`;}
function renderBacklog(){const tasks=backlogTasks(state);return heading('Накопитель','Все дела, которым нужно найти место в расписании.')+renderBacklogCounters()+quickBacklogForm()+`<section class="panel">${tasks.map(t=>`<article class="backlog-item">${taskRow(t)}</article>`).join('')||'<div class="empty">Накопитель пока пуст.</div>'}</section>`;}
function placementForm(id){const task=findTask(state,id);if(!task)return;const slots=state.slots.filter(s=>canPlaceInSlot(s)).sort((a,b)=>a.date.localeCompare(b.date)||a.start.localeCompare(b.start));if(!slots.length){modal('Пока нет интервалов',`<p>Сначала выделите время для вагончика.</p><div class="actions">${btn('Отмена','close')}${btn('Создать интервал','schedule-task',`data-id="${id}"`,'primary')}</div>`);return;}const suggested=slots.find(s=>s.id===task.slotId)||slots.find(s=>s.category===task.category&&s.date===task.date)||slots.find(s=>s.category===task.category&&(!task.date||s.date>=task.date))||slots.find(s=>s.category===task.category)||slots[0];modal('Положить задачу в вагончик',`<p>${esc(task.title)}</p><form id="placement-form" data-id="${id}">${field('Выберите вагончик и время',select('slotId',slots.map(s=>[s.id,`${new Date(s.date+'T12:00:00').toLocaleDateString('ru-RU')} · ${cat(s.category).name} · ${s.start}–${endTime(s.start,s.duration)}`]),suggested.id))}<p class="muted small">Дата и категория задачи изменятся на выбранные. Уже потраченное время останется в истории.</p>${actions('<button class="primary">Положить в вагончик</button>')}</form>`);}
function proposePlacement(id,slotId,confirmed=false){if(state.timer?.task===id){toast('Сначала завершите текущую фокус-сессию этой задачи.');return;}const task=findTask(state,id),slot=state.slots.find(s=>s.id===slotId);if(!task||!slot){toast('Задача или интервал больше не существуют.');return;}if(!canPlaceInSlot(slot)){toast('Этот вагончик уже закончился. Выберите будущее время.');return;}const proposed=structuredClone(state);try{placeTask(proposed,id,slotId);}catch(e){toast(e.message);return;}const capacity=slotOccupancy(proposed,slot);if(capacity.overflow&&!confirmed){modal('Не хватает времени в вагончике',`<p>${esc(cat(slot.category).name)} · ${dateFmt(slot.date)}</p><p>После переноса не поместится ${Math.ceil(capacity.overflow)} мин. Не поместившиеся дела будут видны в накопителе.</p><div class="actions">${btn('Выбрать другой вагончик','place-open',`data-id="${id}"`)}${btn('Всё равно переместить','place-confirm',`data-id="${id}" data-slot="${slotId}"`,'primary')}</div>`);return;}placeTask(state,id,slotId);save();close();render();toast('Задача помещена в выбранный вагончик');}
function removeTask(id){if(state.timer?.task===id)stopSession(false);const record=deleteTask(state,id);if(!record)return;lastDeletion={...record,userId:account.id};save();if($('#modal').open)close();render();toast('Задача удалена',true);}
function undoDeletion(){if(!lastDeletion||lastDeletion.userId!==account?.id)return;if(restoreTask(state,lastDeletion)){lastDeletion=null;save();render();toast('Удаление отменено');}}
function sendToBacklog(id){if(state.timer?.task===id)stopSession(false);if(!stashTask(state,id))return;save();close();render();toast('Задача перенесена в накопитель без даты');}
function defaultPaletteDate(){return week===monday(dateKey())?dateKey():week;}
document.addEventListener('submit',e=>{if(e.target.id!=='placement-form')return;e.preventDefault();proposePlacement(e.target.dataset.id,new FormData(e.target).get('slotId'));});
document.addEventListener('dragstart',e=>{const item=e.target.closest?.('[data-drag-kind]');if(!item)return;if(item.dataset.dragKind==='task'&&e.target.closest('button,input,a')){e.preventDefault();return;}draggedEntity={kind:item.dataset.dragKind,id:item.dataset.taskId||item.dataset.category};e.dataTransfer.effectAllowed=draggedEntity.kind==='task'?'move':'copyMove';e.dataTransfer.setData('text/plain',draggedEntity.id||'busy');e.dataTransfer.setData('application/x-paravoziki',JSON.stringify(draggedEntity));});
function clearDropTargets(){document.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'));}
document.addEventListener('dragover',e=>{if(!draggedEntity)return;const target=draggedEntity.kind==='task'?e.target.closest?.('[data-slot-id]'):e.target.closest?.('[data-drop-date]');if(!target)return;if(draggedEntity.kind==='task'){const slot=state.slots.find(s=>s.id===target.dataset.slotId);if(!slot||!canPlaceInSlot(slot))return;}else if(!canSchedule(target.dataset.dropDate,target.dataset.dropStart||'23:59'))return;e.preventDefault();e.dataTransfer.dropEffect=draggedEntity.kind==='task'?'move':'copy';clearDropTargets();target.classList.add('drop-target');});
document.addEventListener('dragleave',e=>{const target=e.target.closest?.('.drop-target');if(target&&!target.contains(e.relatedTarget))target.classList.remove('drop-target');});
document.addEventListener('dragend',()=>{if(draggedEntity?.kind!=='task')suppressPaletteClickUntil=Date.now()+500;draggedEntity=null;clearDropTargets();});
document.addEventListener('drop',e=>{if(!draggedEntity)return;const entity=draggedEntity;draggedEntity=null;clearDropTargets();e.preventDefault();if(entity.kind==='task'){const slot=e.target.closest?.('[data-slot-id]');if(slot)proposePlacement(entity.id,slot.dataset.slotId);else toast('Перетащите задачу на карточку вагончика.');}else{const dayTarget=e.target.closest?.('[data-drop-date]');if(!dayTarget)return;if(!canSchedule(dayTarget.dataset.dropDate,dayTarget.dataset.dropStart||'23:59')){toast('Это время уже прошло.');return;}suppressPaletteClickUntil=Date.now()+500;if(entity.kind==='category')showSlot(undefined,dayTarget.dataset.dropDate,entity.id,120);else if(entity.kind==='busy')showUnavailable(dayTarget.dataset.dropDate,60);if(dayTarget.dataset.dropStart&&$('#modal input[name=start]'))$('#modal input[name=start]').value=dayTarget.dataset.dropStart;}});

document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches?.('.wagon')){e.preventDefault();e.target.click();}});

function renderTopbar(title){return `<div class="topbar"><span class="eyebrow">Личное пространство / ${esc(title)}</span><p>${new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})}</p>${title==='Неделя'?'':btn('↻','refresh-plan','aria-label="Обновить задачи" title="Обновить задачи"','icon-button backlog-counter-refresh')}</div>`;}

function occupancyScale(s){const o=slotOccupancy(state,s);return `<div class="coach-load ${o.overflow?'is-overloaded':''}" role="img" aria-label="Запланировано ${o.planned} из ${o.capacity} минут. Одно деление — 15 минут${o.overflow?'. Перегрузка '+o.overflow+' минут':''}"><div class="coach-load-label"><span>${o.planned} / ${o.capacity} мин</span>${o.overflow?`<span>+${o.overflow}</span>`:''}</div><div class="coach-segments" aria-hidden="true">${o.segments.map(q=>`<span class="coach-segment" style="flex-grow:${q.minutes};--filled:${q.filled*100}%"></span>`).join('')}</div></div>`;}
function slotCoach(s){const c=cat(s.category),ts=tasksInSlot(state,s),o=slotOccupancy(state,s);return `<div class="rail-coach ${o.overflow?'overloaded-coach':''}" data-slot-id="${s.id}" style="--color:${c.color}"><div class="coach-toolbar">${btn('✎','slot',`data-id="${s.id}" data-date="${s.date}" aria-label="Изменить интервал ${esc(c.name)}" title="Изменить интервал"`,'icon-button interval-edit')}${btn('×','delete-slot',`data-id="${s.id}" aria-label="Удалить интервал ${esc(c.name)}" title="Удалить интервал"`,'icon-button task-delete')}</div><button class="coach-open" data-action="coach-detail" data-id="${s.id}" aria-label="${esc(c.name)}, ${dateFmt(s.date)}, ${s.start}–${endTime(s.start,s.duration)}, ${ts.length} дел, занято ${o.planned} из ${o.capacity} минут" title="${esc(c.name)} · ${s.start}–${endTime(s.start,s.duration)} · ${ts.length} дел"><strong>${esc(c.name)}</strong><span class="coach-time">${s.start}–${endTime(s.start,s.duration)}</span>${occupancyScale(s)}</button><button type="button" class="coach-resize coach-resize-start" data-resize-slot="${s.id}" data-edge="start" aria-label="Изменить начало ${esc(c.name)}" title="Потяните край · шаг 15 минут"></button><button type="button" class="coach-resize coach-resize-end" data-resize-slot="${s.id}" data-edge="end" aria-label="Изменить длительность ${esc(c.name)}" title="Потяните край · шаг 15 минут"></button></div>`;}
function showCoachDetails(id,edit=false){const s=state.slots.find(s=>s.id===id);if(!s)return;const c=cat(s.category),ts=tasksInSlot(state,s);modal(esc(c.name),`<section class="coach-details" data-coach-details="${s.id}" style="--color:${c.color}"><details class="interval-settings" ${edit?'open':''}><summary><span class="muted">${dateFmt(s.date)} · ${s.start}–${endTime(s.start,s.duration)}</span><span class="interval-pencil" aria-label="Изменить время интервала" title="Изменить время интервала">✎</span></summary><form id="slot-form" data-id="${s.id}">${field('Вагончик',categorySelect(s.category))}${field('Дата',input('date','date',s.date,'required'))}${field('Начало',input('start','time',s.start,'required'))}${field('Продолжительность, минуты',input('duration','number',s.duration,'required min="15" max="1440" step="15"'))}<button class="primary">Сохранить интервал</button></form></details>${occupancyScale(s)}<p class="small muted">Одно деление — 15 минут. Закрашенное время занято задачами.</p>${ts.map(taskRow).join('')||'<p class="empty">В этом вагончике пока нет дел.</p>'}${canPlaceInSlot(s)?`<form id="coach-task-form" data-id="${s.id}" class="coach-add-form"><h3>Добавить дело</h3>${field('Название',input('title','text','','required maxlength="240" placeholder="Что нужно сделать?"'))}${field('Продолжительность, минуты',input('estimate','number',30,'required min="1" max="1440"'))}<button class="primary">Добавить дело</button></form>`:''}<div class="actions">${btn('Закрыть','close')}${btn('×','delete-slot',`data-id="${s.id}" aria-label="Удалить интервал"`,'icon-button task-delete')}</div></section>`);}

function renderTimeline(dates){return `<div class="timeline-scroll rail-scroll" aria-label="Расписание: дни строками, время по горизонтали"><div class="rail-calendar"><div class="rail-time-head"><div class="rail-corner">День</div><div class="rail-hour-labels">${Array.from({length:16},(_,h)=>`<span style="left:${h/15*100}%">${String(h+8).padStart(2,'0')}:00</span>`).join('')}</div></div>${dates.map((d,i)=>{const elapsed=pastMinutes(d),entries=timelineLanes([...slotsOn(state,d).map(s=>({start:s.start,duration:s.duration,html:slotCoach(s)})),...state.unavailable.filter(e=>unavailableOn(e,d)).map(e=>({start:e.start,duration:e.duration,html:`<div class="rail-coach rail-busy ${e.category?'calendar-categorized':''}" style="--color:${esc(state.categories.find(c=>c.id===e.category)?.color||'#92998b')}"><div class="coach-toolbar">${btn('✎','busy-detail',`data-id="${e.id}" aria-label="Изменить встречу"`,'icon-button interval-edit')}${btn('×','delete-event',`data-id="${e.id}" aria-label="Убрать ${esc(e.title)} из расписания" title="${e.source==='google'?'Скрыть в Паровозиках, оставить в Google Calendar':'Удалить событие'}"`,'icon-button task-delete')}</div><button class="busy-coach-label" type="button" data-action="busy-detail" data-id="${e.id}" title="${esc(e.title)} · ${e.start}–${endTime(e.start,e.duration)}"><strong>${esc(e.title)}</strong>${e.category?`<small>${esc(state.categories.find(c=>c.id===e.category)?.name||'')}</small>`:''}<span class="coach-time">${e.start}–${endTime(e.start,e.duration)}</span></button></div>`}))].filter(e=>minutes(e.start)<1380&&minutes(e.start)+e.duration>480));const lanes=Math.max(1,...entries.map(e=>e.lane+1));return `<section class="rail-day ${d===dateKey()?'today':''}" style="--lanes:${lanes}"><div class="rail-day-label"><span>${days[i]}${d===dateKey()?'<small>сегодня</small>':''}</span><b>${new Date(d+'T12:00:00').getDate()}</b></div><div class="rail-track" data-timeline-date="${d}">${Array.from({length:60},(_,n)=>{const start=endTime('08:00',n*15);return `<button class="rail-cell" style="left:${n/60*100}%" data-action="timeline-add" data-date="${d}" data-start="${start}" data-drop-date="${d}" data-drop-start="${start}" aria-label="Добавить интервал ${dateFmt(d)} ${start}" ${!canSchedule(d,start)?'disabled':''}></button>`;}).join('')}${elapsed>480?`<div class="rail-past" style="width:${Math.max(0,Math.min(900,elapsed-480))/9}%" aria-label="Прошедшее время"></div>`:''}${entries.map(e=>`<div class="rail-entry ${minutes(e.start)+e.duration<=elapsed?'rail-elapsed':''}" style="left:${Math.max(0,minutes(e.start)-480)/9}%;width:${(Math.min(1380,minutes(e.start)+e.duration)-Math.max(480,minutes(e.start)))/9}%;top:${e.lane*132+10}px">${e.html}</div>`).join('')}${d===dateKey()&&elapsed>=480&&elapsed<=1380?`<div class="rail-now" style="left:${(elapsed-480)/9}%" aria-label="Текущее время"><span>Сейчас</span></div>`:''}</div></section>`;}).join('')}</div></div><p class="rail-key">Одно деление загрузки — 15 минут · нажмите на вагончик, чтобы открыть дела.</p>`;}
setInterval(()=>{if(account&&view==='week'&&!$('#modal').open&&!draggedEntity&&!coachGesture){const scroll=$('.timeline-scroll'),top=scroll?.scrollTop,left=scroll?.scrollLeft;if(scroll){const wrapper=document.createElement('div');wrapper.innerHTML=renderTimeline(Array.from({length:7},(_,i)=>addDays(week,i)));scroll.innerHTML=wrapper.querySelector('.timeline-scroll').innerHTML;scroll.scrollTop=top;scroll.scrollLeft=left;}}},60000);

function futureStart(date,duration){const suggested=suggestStart(state,date,duration);return canSchedule(date,suggested)?suggested:endTime('00:00',Math.min(1439,Math.ceil(pastMinutes(date)/15)*15));}

function gestureTime(track,x){const r=track.getBoundingClientRect();return Math.max(480,Math.min(1380,Math.round((480+(x-r.left)/r.width*900)/15)*15));}
document.addEventListener('pointerdown',e=>{if(e.button!==0)return;const resize=e.target.closest('[data-resize-slot]'),open=e.target.closest('.coach-open');if(!resize&&!open)return;const coach=e.target.closest('[data-slot-id]'),slot=state.slots.find(s=>s.id===(resize?.dataset.resizeSlot||coach?.dataset.slotId));if(!slot)return;const entry=coach.closest('.rail-entry'),track=entry.closest('.rail-track');coachGesture={id:slot.id,edge:resize?.dataset.edge||'move',x:e.clientX,y:e.clientY,pointerId:e.pointerId,target:e.target,entry,track,original:{...slot},active:false,grab:gestureTime(track,e.clientX)-minutes(slot.start)};if(resize){e.preventDefault();e.target.setPointerCapture(e.pointerId);}});
document.addEventListener('pointermove',e=>{const g=coachGesture;if(!g||e.pointerId!==g.pointerId)return;if(!g.active&&Math.hypot(e.clientX-g.x,e.clientY-g.y)<5)return;e.preventDefault();if(!g.active){g.active=true;g.ghost=g.entry.cloneNode(true);g.ghost.classList.add('coach-gesture-preview');g.ghost.removeAttribute('id');g.ghost.style.position='fixed';g.ghost.style.zIndex='50';g.ghost.style.pointerEvents='none';g.ghost.style.opacity='.8';document.body.append(g.ghost);document.body.classList.add('is-coach-dragging');g.target.setPointerCapture?.(e.pointerId);}const track=g.edge==='move'?document.elementFromPoint(e.clientX,e.clientY)?.closest('.rail-track'):g.track;if(!track){g.candidate=null;return;}let start=minutes(g.original.start),end=start+g.original.duration;if(g.edge==='move'){start=Math.max(480,Math.min(1380-g.original.duration,gestureTime(track,e.clientX)-g.grab));end=start+g.original.duration;}else if(g.edge==='end')end=Math.max(start+15,gestureTime(track,e.clientX));else start=Math.min(end-15,gestureTime(track,e.clientX));g.candidate={date:track.dataset.timelineDate,start:endTime('00:00',start),duration:end-start};const r=track.getBoundingClientRect();g.ghost.style.left=(r.left+(start-480)/900*r.width)+'px';g.ghost.style.top=(g.edge==='move'?r.top+10:g.entry.getBoundingClientRect().top)+'px';g.ghost.style.width=((end-start)/900*r.width)+'px';g.ghost.style.height='108px';g.ghost.querySelector('.coach-time').textContent=g.candidate.start+'–'+endTime(g.candidate.start,g.candidate.duration);});
function finishCoachGesture(e,cancel=false){const g=coachGesture;if(!g||e.pointerId!==g.pointerId)return;coachGesture=null;g.ghost?.remove();document.body.classList.remove('is-coach-dragging');if(!g.active)return;suppressCoachClickUntil=Date.now()+500;if(cancel||!g.candidate)return;try{if(state.timer&&tasksInSlot(state,g.original).some(t=>t.id===state.timer.task))throw Error('Сначала завершите фокус-сессию в этом вагончике.');changeSlotTiming(state,g.id,g.candidate.date,g.candidate.start,g.candidate.duration);save();render();toast(g.edge==='move'?'Вагончик перенесён вместе с делами':'Длительность изменена');}catch(error){toast(error.message);}}
document.addEventListener('pointerup',e=>finishCoachGesture(e));document.addEventListener('pointercancel',e=>finishCoachGesture(e,true));
document.addEventListener('keydown',e=>{const h=e.target.closest('[data-resize-slot]');if(!h||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const s=state.slots.find(s=>s.id===h.dataset.resizeSlot);if(!s)return;const delta=e.key==='ArrowRight'?15:-15;try{changeSlotTiming(state,s.id,s.date,h.dataset.edge==='start'?endTime('00:00',minutes(s.start)+delta):s.start,s.duration+(h.dataset.edge==='start'?-delta:delta));save();render();}catch(error){toast(error.message);}});

function calendarRange(){return {from:addDays(week,-14),to:addDays(week,28),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone};}
function calendarPanel(){const c=calendarConnection;return `<section class="panel"><h2>Google Calendar</h2>${c?.connected?`<span class="pill">Подключён · только чтение</span><p class="muted">События календаря показываются серыми вагончиками. Обновление — при открытии приложения и каждые 5 минут, пока оно открыто.</p><p class="small muted">${c.lastSync?'Последнее обновление: '+new Date(c.lastSync).toLocaleString('ru-RU'):'Ещё не обновлялся'}</p>${c.error?`<p class="warn">${esc(c.error)}</p>`:''}<div class="actions">${btn('Обновить календарь','calendar-sync','','primary')}${btn('Изменить подключение','calendar-connect')}${btn('Отключить','calendar-disconnect','','small')}</div>`:`<p class="muted">Подключите календарь по секретной ссылке iCal. События будут копироваться как занятое время, включая повторяющиеся и на весь день.</p>${btn('Подключить Google Calendar','calendar-connect','','primary')}`}</section>`;}
function showCalendarConnect(){modal('Подключить Google Calendar',`<form id="calendar-form"><p>В Google Calendar откройте настройки нужного календаря → «Интеграция календаря» → «Секретный адрес в формате iCal».</p><p class="small muted">Календарь остаётся закрытым. Ссылка хранится в зашифрованном виде и не попадает в экспорт плана.</p>${field('Секретная ссылка iCal',input('url','password','','required autocomplete="off" spellcheck="false" placeholder="https://calendar.google.com/calendar/ical/…/basic.ics" aria-describedby="calendar-connect-error"'))}<div id="calendar-connect-error" class="calendar-connect-error" role="alert" hidden></div><p class="small"><a href="https://support.google.com/calendar/answer/37648?hl=ru" target="_blank" rel="noopener noreferrer">Как найти ссылку в Google Calendar</a></p>${actions('<button class="primary">Подключить</button>')}</form>`);}
async function fetchCalendar(auto=false){if(!account)return;try{const userId=account.id;const connection=await requestAPI('/api/calendar/status');if(account?.id!==userId)return;calendarConnection=connection;if(view==='settings'&&!$('#modal').open)render();if(auto&&calendarConnection.connected)syncCalendar(false);}catch(e){if(view==='settings')toast(e.message);}}
async function syncCalendar(manual=false){if(!account||calendarBusy||!calendarConnection?.connected)return;if(pendingPlan||syncBusy||syncBlocked||state.timer||coachGesture||draggedEntity||$('#modal').open){if(manual)toast('Сначала сохраните изменения и завершите фокус-сессию.');return;}calendarBusy=true;const userId=account.id;try{const result=await requestAPI('/api/calendar/sync',{method:'POST',body:JSON.stringify(calendarRange())});if(account?.id!==userId)return;calendarConnection={...calendarConnection,...result,error:null};if(!result.unchanged)await refreshRemotePlan(true);if(view==='settings')render();if(manual)toast('Календарь обновлён');}catch(e){calendarConnection={...calendarConnection,error:e.message};if(view==='settings')render();if(manual)toast(e.message);}finally{calendarBusy=false;}}
async function disconnectCalendar(){if(pendingPlan||syncBusy||state.timer){toast('Сначала сохраните изменения и завершите фокус-сессию.');return;}try{calendarConnection=await requestAPI('/api/calendar/disconnect',{method:'POST',body:'{}'});await refreshRemotePlan(true);render();toast('Календарь отключён. События Google убраны из расписания.');}catch(e){toast(e.message);}}
document.addEventListener('submit',async e=>{if(e.target.id!=='calendar-form')return;e.preventDefault();const form=e.target,button=form.querySelector('button.primary'),errorBox=form.querySelector('#calendar-connect-error'),urlInput=form.elements.url;const showError=message=>{errorBox.textContent=message;errorBox.hidden=false;urlInput.setAttribute('aria-invalid','true');};errorBox.hidden=true;urlInput.removeAttribute('aria-invalid');if(pendingPlan||syncBusy||state.timer){showError('Сначала сохраните изменения и завершите фокус-сессию.');return;}button.disabled=true;button.textContent='Подключаем…';form.setAttribute('aria-busy','true');try{calendarConnection=await requestAPI('/api/calendar/connect',{method:'POST',body:JSON.stringify({url:new FormData(form).get('url').trim(),...calendarRange()})});form.reset();close();$('#modal').innerHTML='';await refreshRemotePlan(true);render();toast('Календарь подключён, события добавлены в расписание');}catch(error){showError(error.message);button.disabled=false;button.textContent='Подключить';}finally{form.removeAttribute('aria-busy');}});
setInterval(()=>{if(!document.hidden)syncCalendar(false);},300000);

function showCalendarEvent(id){
 const ev=state.unavailable.find(x=>x.id===id);if(!ev)return;
 modal(ev.source==='google'?'Встреча из календаря':'Изменить событие',`<form id="calendar-event-edit" data-id="${id}">${field('Название',input('title','text',ev.title,'required maxlength="240"'))}${field('Вагончик',select('category',[['','Занятое время'],...state.categories.map(c=>[c.id,c.name])],ev.category||''))}${ev.source==='google'?`<p class="small muted">${dateFmt(ev.from)} · начало ${ev.start}</p>`:`${field('Дата / начало периода',input('from','date',ev.from,'required'))}${field('Начало',input('start','time',ev.start,'required'))}${field('Повторение',select('repeat',[['once','Один раз'],['weekly','Еженедельно']],ev.repeat||'once'))}${field('Конец периода',input('until','date',ev.until||''))}`}${field('Продолжительность, минуты',input('duration','number',ev.duration,'required min="1" max="1440" step="1"'))}${ev.source==='google'?'<p class="small muted">Только эта встреча в Паровозиках. Изменения сохранятся после синхронизации. Google Calendar не изменится.</p>':''}${actions('<button class="primary">Сохранить</button>')}</form>`);
}
document.addEventListener('submit',e=>{
 if(e.target.id!=='calendar-event-edit')return;e.preventDefault();const form=e.target,ev=state.unavailable.find(x=>x.id===form.dataset.id);if(!ev)return;
 const d=Object.fromEntries(new FormData(form)),duration=Number(d.duration),title=d.title.trim();if(!title||!Number.isInteger(duration)||duration<1||duration>1440)return;
 if(minutes(d.start||ev.start)+duration>1440){toast('Встреча должна заканчиваться в тот же день.');return;}
 const edit={title,category:d.category||null,duration};if(ev.source==='google'){(state.calendarOverrides ||= {})[ev.id]=edit;}else{if(d.until&&d.until<d.from){toast('Конец периода раньше начала.');return;}Object.assign(edit,{from:d.from,start:d.start,repeat:d.repeat,until:d.until,weekday:(new Date(d.from+'T12:00:00').getDay()+6)%7});}Object.assign(ev,edit);save();close();render();toast('Встреча изменена в Паровозиках');
});

document.addEventListener('submit',e=>{if(e.target.id!=='coach-task-form')return;e.preventDefault();const s=state.slots.find(s=>s.id===e.target.dataset.id);if(!s||!canPlaceInSlot(s)){toast('Этот вагончик уже закончился.');return;}const d=Object.fromEntries(new FormData(e.target)),estimate=Number(d.estimate);if(!d.title.trim()||!Number.isFinite(estimate)||estimate<1||estimate>1440)return;state.tasks.push({id:uid(),title:d.title.trim(),category:s.category,date:s.date,originalDate:s.date,slotId:s.id,estimate,actual:0,done:false,createdAt:Date.now()});save();render();showCoachDetails(s.id);toast('Дело добавлено в этот вагончик');});

function taskDurationControl(t){return `<span class="dense-estimate task-duration-control">${btn('−','task-duration',`data-id="${t.id}" data-delta="-15" aria-label="Уменьшить длительность: ${esc(t.title)}" title="Минус 15 минут" ${t.estimate<=1?'disabled':''}`,'duration-step')}<span>${t.estimate} мин</span>${btn('+','task-duration',`data-id="${t.id}" data-delta="15" aria-label="Увеличить длительность: ${esc(t.title)}" title="Плюс 15 минут" ${t.estimate>=1440?'disabled':''}`,'duration-step')}${t.actual?`<span class="muted"> · факт ${Math.round(t.actual)}</span>`:''}</span>`;}
